using System;
using System.IO;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.SceneManagement;
using HarborValeGreybox.Driving;
using HarborValeGreybox.Garage;
using HarborValeGreybox.Racing;
using HarborValeGreybox.SportsTest;
namespace HarborValeGreybox.Launch {
public sealed class LaunchPlayerProbe:MonoBehaviour {
 static string folder;List<string> lines=new List<string>();double deadline;bool failed;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Prepare(){var args=Environment.GetCommandLineArgs();int i=Array.IndexOf(args,"--launch-smoke-dir");if(!Debug.isDebugBuild||i<0||i+1>=args.Length){folder=null;return;}folder=Path.GetFullPath(args[i+1]);Directory.CreateDirectory(folder);DocksideTrialDirector.SavePathOverrideForTests=Path.Combine(folder,"isolated-v3.json");}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Hook(){if(folder==null)return;var root=new GameObject("Unified player verification | isolated account");DontDestroyOnLoad(root);root.AddComponent<LaunchPlayerProbe>();}
 void OnEnable(){Application.logMessageReceived+=Log;}void OnDisable(){Application.logMessageReceived-=Log;}
 void Log(string m,string s,LogType t){if(t==LogType.Error||t==LogType.Exception)Fail(m);}
 void Fail(string text){if(failed)return;failed=true;lines.Add("FAIL "+text);File.WriteAllLines(Path.Combine(folder,"player-smoke.txt"),lines);Application.Quit(1);}
 void Check(bool yes,string text){if(!yes){Fail(text);throw new Exception(text);}lines.Add("PASS "+text);}
 void Update(){if(!failed&&deadline>0&&Time.realtimeSinceStartupAsDouble>deadline)Fail("Unified player verification timed out");}
 static TrialSession Finish(TrialDefinition d){var s=new TrialSession(d);s.Tick(4,Vector3.zero,Vector3.zero);s.Tick(90,Vector3.zero,Vector3.zero);foreach(var g in d.checkpoints)s.Tick(.02f,g.Position-g.Forward,g.Position+g.Forward);return s;}
 IEnumerator Wait(Func<bool> ready){double until=Time.realtimeSinceStartupAsDouble+35;while(!ready()){if(Time.realtimeSinceStartupAsDouble>until){Check(false,"Scene startup timeout");yield break;}yield return null;}yield return new WaitForSecondsRealtime(.3f);}
 IEnumerator Capture(string name){yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Path.Combine(folder,name+".png"));yield return new WaitForSecondsRealtime(.3f);}
 void OneCar(){Check(UnityEngine.Object.FindObjectsByType<FinchVehicle>(FindObjectsSortMode.None).Length==1&&UnityEngine.Object.FindObjectsByType<WheelCollider>(FindObjectsSortMode.None).Length==4,"Exactly one controller and four wheel contacts after transition");Check(UnityEngine.Object.FindObjectsByType<HarborValeLaunch>(FindObjectsSortMode.None).Length==1&&UnityEngine.Object.FindObjectsByType<AudioListener>(FindObjectsSortMode.None).Length==1,"Exactly one persistent launcher and one audio listener");}
 IEnumerator Start(){deadline=Time.realtimeSinceStartupAsDouble+180;yield return new WaitForSecondsRealtime(1);Check(SceneManager.GetActiveScene().name==HarborValeLaunch.MenuScene,"Unified Windows player starts at real mode menu");Check(UnityEngine.Object.FindAnyObjectByType<FinchVehicle>()==null&&UnityEngine.Object.FindAnyObjectByType<DocksideTrialDirector>()==null,"Menu creates no car or career account");yield return Capture("Launch_Menu");Check(HarborValeLaunch.Instance.Open(HarborValeLaunch.CityScene),"Finch selection starts scene transition");yield return Wait(()=>UnityEngine.Object.FindAnyObjectByType<FinchGarage>()?.Catalog!=null&&!HarborValeLaunch.Instance.Busy);var garage=UnityEngine.Object.FindAnyObjectByType<FinchGarage>();var trial=garage.Trial;OneCar();Check(trial.Store.PathName==DocksideTrialDirector.SavePathOverrideForTests,"All seeded progress confined to explicit isolated fixture");Check(trial.Store.Profile.earnings==0,"Fresh fixture expected");for(int i=0;i<4;i++)trial.Store.Settle(Finish(trial.Definition),out _);Check(garage.Open(),"Actual Finch garage opens after menu entry");for(int i=0;i<4;i++){garage.Select(i);Check(garage.BuySelected(),"Paid part "+i+" installs after menu entry");}garage.Close();Check(trial.Store.Profile.availableCredits==250,"All four paid receipts leave 250 fixture credits");yield return Capture("Launch_Finch");string paid=File.ReadAllText(trial.Store.PathName);Check(trial.BeginRun(),"Time trial starts before transition");Check(HarborValeLaunch.Instance.Open(HarborValeLaunch.MenuScene),"Returning to menu explicitly abandons active race");yield return Wait(()=>SceneManager.GetActiveScene().name==HarborValeLaunch.MenuScene&&!HarborValeLaunch.Instance.Busy);Check(File.ReadAllText(DocksideTrialDirector.SavePathOverrideForTests)==paid,"Abandoned run gives no payout or changed profile");Check(HarborValeLaunch.Instance.Open(HarborValeLaunch.SportsScene),"Apex selection starts scene transition");yield return Wait(()=>UnityEngine.Object.FindAnyObjectByType<ApexTestDrive>()?.Ready==true&&!HarborValeLaunch.Instance.Busy);OneCar();var sports=UnityEngine.Object.FindAnyObjectByType<ApexTestDrive>();var timer=UnityEngine.Object.FindAnyObjectByType<SportsAccelerationHUD>();Check(UnityEngine.Object.FindAnyObjectByType<DocksideTrialDirector>()==null&&UnityEngine.Object.FindAnyObjectByType<FinchGarage>()==null&&sports.Step==0,"Apex starts stock without any career services");sports.Car.externalInput=true;sports.Car.commandedPedal=0;for(int i=1;i<=4;i++)Check(sports.SelectStep(i),"Free Apex package "+i+" applies");yield return Wait(()=>timer.ReadyToArm);Check(timer.Arm(),"Stopped grounded sports car arms live timer");sports.Car.commandedPedal=1;yield return new WaitForSecondsRealtime(2);yield return Capture("Launch_LiveTiming");yield return Wait(()=>timer.Run.State==AccelerationState.Finished||timer.Run.State==AccelerationState.Cancelled);Check(timer.Run.State==AccelerationState.Finished&&timer.Run.Seconds>2&&timer.Run.Seconds<20,"Actual driving completes live 0-100 in "+timer.Run.Seconds.ToString("F2")+" seconds");sports.Car.commandedPedal=0;sports.Car.commandedHandbrake=true;yield return Capture("Launch_TimingResult");Check(timer.Best[4]>0&&timer.Best[0]<0,"Best time belongs only to tested configuration");sports.Car.Recover();yield return Wait(()=>timer.ReadyToArm);Check(timer.Arm(),"Stopped car re-arms after recovery");sports.Car.Recover();yield return new WaitForFixedUpdate();yield return null;Check(timer.Run.State==AccelerationState.Cancelled,"Recovery cancels an armed test");yield return Wait(()=>timer.ReadyToArm);Check(timer.Arm()&&sports.SelectStep(4),"Same configuration can be reapplied during armed setup");yield return new WaitForFixedUpdate();yield return null;Check(timer.Run.State==AccelerationState.Cancelled,"Reinstalling same configuration cancels stale timing");Check(File.ReadAllText(DocksideTrialDirector.SavePathOverrideForTests)==paid,"Sports testing never changes career fixture");Check(HarborValeLaunch.Instance.Open(HarborValeLaunch.MenuScene),"Sports returns to menu");yield return Wait(()=>SceneManager.GetActiveScene().name==HarborValeLaunch.MenuScene&&!HarborValeLaunch.Instance.Busy);Check(HarborValeLaunch.Instance.Open(HarborValeLaunch.CityScene),"Finch can be selected again in same process");yield return Wait(()=>UnityEngine.Object.FindAnyObjectByType<FinchGarage>()?.Catalog!=null&&!HarborValeLaunch.Instance.Busy);garage=UnityEngine.Object.FindAnyObjectByType<FinchGarage>();trial=garage.Trial;OneCar();Check(trial.Store.Profile.availableCredits==250&&trial.Store.Profile.spending.Count==4&&trial.vehicle.Engine.definition.SampleTorque(4500)==162,"Repeated scene entry reloads complete paid Finch build without extra charge");Check(trial.vehicle.frontDriveShare==1&&trial.vehicle.lateralGrip==1.1f&&trial.vehicle.downforceCoefficient==.35f,"Apex handling never leaks onto Finch");Check(UnityEngine.Object.FindObjectsByType<DocksideTrialDirector>(FindObjectsSortMode.None).Length==1&&UnityEngine.Object.FindObjectsByType<FinchGarage>(FindObjectsSortMode.None).Length==1,"Exactly one trial and garage after repeated selection");yield return Capture("Launch_Finch_Reload");
  // Inject only a test store write failure to exercise the actual leave guard.
  var working=trial.Store;var fault=new RaceProgressStore(working.PathName,trial.Definition,()=>{throw new IOException("Injected hub save failure");});typeof(DocksideTrialDirector).GetProperty("Store").SetValue(trial,fault);typeof(DocksideTrialDirector).GetProperty("Session").SetValue(trial,Finish(trial.Definition));Check(!trial.TrySettlement()&&!HarborValeLaunch.Instance.Open(HarborValeLaunch.MenuScene),"Unpaid valid result blocks menu departure when save fails");typeof(DocksideTrialDirector).GetProperty("Store").SetValue(trial,working);Check(trial.TrySettlement(),"Retry settles preserved valid result");Check(HarborValeLaunch.Instance.Open(HarborValeLaunch.MenuScene),"Menu departure resumes after result saves");yield return Wait(()=>SceneManager.GetActiveScene().name==HarborValeLaunch.MenuScene&&!HarborValeLaunch.Instance.Busy);Check(HarborValeLaunch.Instance.Open(HarborValeLaunch.SportsScene),"Apex can be selected again");yield return Wait(()=>UnityEngine.Object.FindAnyObjectByType<ApexTestDrive>()?.Ready==true&&!HarborValeLaunch.Instance.Busy);OneCar();timer=UnityEngine.Object.FindAnyObjectByType<SportsAccelerationHUD>();Check(timer.Best[4]<0,"New sports visit starts a fresh timing session");Check(UnityEngine.Object.FindAnyObjectByType<ApexTestDrive>().Step==0,"New sports visit resets free parts to stock");File.WriteAllLines(Path.Combine(folder,"player-smoke.txt"),lines);Application.Quit(0);
 }
}
}
